class LocaleService {
  constructor(){try{this.language=globalThis.VesaPrefs?.read?.().language||localStorage.getItem('vesa.ppm.language')||'en'}catch{this.language='en'}if(!['en','bn','hi','ta','es'].includes(this.language))this.language='en'}
  set(language){if(!['en','bn','hi','ta','es'].includes(language))return;this.language=language;try{localStorage.setItem('vesa.ppm.language',language);if(globalThis.VesaPrefs?.write){globalThis.VesaPrefs.write({...globalThis.VesaPrefs.read(),language});}}catch{}document.documentElement.lang=language}
  checkpoint(id,english){return this.language==='es'?(PPM_ES_TEXT[english]||english):(PPM_SENTENCES[id]?.[this.language]||english)}
  sentence(key,english){return this.language==='es'?(PPM_ES_TEXT[english]||english):(PPM_SENTENCES[key]?.[this.language]||english)}
}

